-- 0090_en_levels_replace_cambridge_oxford.sql
-- Replaces every English CEFR level that came from Cambridge or the Oxford 3000/5000 list
-- (#39, #18).
--
-- lex.entries held 7,450 English levels with provenance.level 'cambridge', scraped from the
-- first CEFR badge on dictionary.cambridge.org's English-Vietnamese page, and 365 with
-- 'oxford-3000-5000'. Neither licence lets a public site store or show them: Cambridge
-- University Press & Assessment's website terms allow personal, non-commercial use only and
-- forbid storing the site's content on a server, and Oxford Learner's Dictionaries' terms
-- (clause 3.1.3) forbid displaying any part of the lists on a network open to anyone who is
-- not an Authorised User. The Cambridge badge was also often wrong: en:abolition and
-- en:adolescence were A1.
--
-- A headword on the CEFR-J Wordlist (A1-B2; Tono Laboratory, TUFS, free for commercial use
-- with citation) or on the Octanove C1/C2 profile (CC BY-SA 4.0) takes that list's level,
-- the lowest one where the list gives several, with level_is_estimated false and
-- provenance.level set to the list's source id. Any other entry takes the pipeline's
-- frequency estimate (zhesen-pipeline `level_for_zipf` over wordfreq 3.1.1's zipf, the same
-- gate as `frequency_fields`: single-token words only), with level_is_estimated true and no
-- provenance.level key, as every estimated English level on production has. The rest of
-- provenance is kept. Measured on production on 2026-09-29:
--
-- | Old source | CEFR-J | Octanove | Frequency estimate | No level | Total | Level changes |
-- | --- | --- | --- | --- | --- | --- | --- |
-- | cambridge | 2,731 | 278 | 4,430 | 11 | 7,450 | 5,435 |
-- | oxford-3000-5000 | 0 | 0 | 359 | 6 | 365 | 324 |
--
-- | Old source | A1 | A2 | B1 | B2 | C1 | C2 | No level |
-- | --- | --- | --- | --- | --- | --- | --- | --- |
-- | cambridge after | 531 | 783 | 1,657 | 2,935 | 1,451 | 82 | 11 |
-- | oxford-3000-5000 after | 13 | 46 | 156 | 117 | 25 | 2 | 6 |
--
-- The 17 entries left with no level are the ones the English build gives none: names,
-- abbreviations, hyphenated and accented forms (Americans, Halloween, Hinduism, HoC, Islam,
-- Judaism, Neptune, apr, atm, fiancé, high-profile, large-scale, long-standing, post-war,
-- thought-provoking, well-being, www).
--
-- The update skips a row whose level, level_is_estimated or provenance.level changed since
-- it was measured, so it is idempotent against the target state. pipeline/english/load.sql
-- keeps a level whose level_is_estimated is false and recomputes an estimated one, so a
-- reload keeps the result.
--
-- TO ROLL BACK: run s3://zhesen-infra-assets-014498663963/data-loads/issue39-undo.sql, which
-- sets each row back to its level, level_is_estimated and provenance.level before this
-- migration where it still holds the values written here, and deletes the
-- schema_migrations row.
update lex.entries e set
  level = v.after_level,
  level_is_estimated = v.after_estimated,
  provenance = case when v.after_source is null then e.provenance - 'level'
                    else e.provenance || jsonb_build_object('level', v.after_source) end
from (values
('en:abandoned', 'B2', false, 'B2', false, 'cefrj-vocabulary'),
('en:abbey', 'A1', false, 'B2', true, null),
('en:abdomen', 'A1', false, 'B2', true, null),
